package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.stats.Formulas;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * Handles the logic for removing a shield from a target creature.<br>
 * This effect is triggered when a skill successfully disarms an opponent's defensive item.
 * @author Mobius
 */
public class DisarmShield extends AbstractEffect
{
	private final int _chance;
	
	/**
	 * Creates a new {@code DisarmShield} effect.<br>
	 * This constructor initializes the shield disarming chance.
	 * @param params The {@code StatSet} containing configuration values.
	 */
	public DisarmShield(StatSet params)
	{
		_chance = params.getInt("chance", 100);
	}
	
	/**
	 * Checks if the effect is triggered instantly.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Checks if the effect can be applied to a target.<br>
	 * This specific effect only triggers if the {@code effected} creature is a {@code Player}.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The skill being used.
	 * @return {@code true} if the target is a player, {@code false} otherwise.
	 */
	@Override
	public boolean canStart(Creature effector, Creature effected, Skill skill)
	{
		return effected.isPlayer();
	}
	
	/**
	 * Calculates the probability of a successful disarm.<br>
	 * It uses the internal chance and compares the two creatures.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The skill being used to trigger the effect.
	 * @return {@code true} if the success roll passes, {@code false} otherwise.
	 */
	@Override
	public boolean calcSuccess(Creature effector, Creature effected, Skill skill)
	{
		return Formulas.calcProbability(_chance, effector, effected, skill);
	}
	
	/**
	 * Executes the instant effect of a skill.<br>
	 * This method removes the shield from the target player.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The {@code Skill} being used.
	 * @param item The {@code Item} associated with the skill.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		final Player player = effected.asPlayer();
		if (player == null)
		{
			return;
		}
		
		player.disarmShield();
	}
}
